        # Split off build metadata (everything after '+')
        if '+' in version:
            version_no_build = version.split('+')[0]
        else:
            version_no_build = version

        # Split off pre-release (everything after '-')
        if '-' in version_no_build:
            version_part, prerelease_part = version_no_build.split('-', 1)
        else:
            version_part = version_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # None means no pre-release (release version)
        # A version with pre-release sorts before one without
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # release version sorts after pre-release
        if pre2 is None:
            return -1  # pre-release sorts before release version

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all digits
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric, compare numerically
                cmp = int(id1) - int(id2)
                if cmp != 0:
                    return -1 if cmp < 0 else 1
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare by ASCII
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def compare_versions(v1, v2):
        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        major1, minor1, patch1, pre1 = parsed1
        major2, minor2, patch2, pre2 = parsed2

        # Compare MAJOR.MINOR.PATCH
        if major1 != major2:
            return -1 if major1 < major2 else 1
        if minor1 != minor2:
            return -1 if minor1 < minor2 else 1
        if patch1 != patch2:
            return -1 if patch1 < patch2 else 1

        # Compare pre-release
        return compare_prerelease(pre1, pre2)

    # Use stable sort to maintain input order for equal precedence
    from functools import cmp_to_key
    return sorted(versions, key=cmp_to_key(compare_versions))

